  public static Eventspy.MapEmpty mapEmptyFromBytes(byte[] data) throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    String dataStr = new String(data).trim();
    if (dataStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "empty data after trimming");
    }
    if (dataStr.startsWith("{") || dataStr.startsWith("[")) {
      try {
        return mapEmptyFromJson(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains(":") && !dataStr.contains("=")) {
      try {
        return mapEmptyFromYaml(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains("=")) {
      try {
        return mapEmptyFromToml(dataStr);
      } catch (Exception e) {
        // Fall through to try binary
      }
    }
    try {
      return mapEmptyFromBinary(data);
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse MapEmpty: unsupported format or invalid data: " + e.getMessage(),
          e);
    }
  }

  public static Eventspy.MapEmpty mapEmptyFromJson(String json) throws ProtoException {
    if (json == null || json.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "json is null or empty");
    }
    try {
      Eventspy.MapEmpty.Builder builder = Eventspy.MapEmpty.newBuilder();
      return builder.build();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Failed to parse MapEmpty from JSON: " + e.getMessage(),
          e);
    }
  }

  public static Eventspy.MapEmpty mapEmptyFromBinary(byte[] data) throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    try {
      return Eventspy.MapEmpty.parseFrom(data);
    } catch (InvalidProtocolBufferException e) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Failed to parse MapEmpty from binary: " + e.getMessage(),
          e);
    }
  }

