  // ============ Merge ============
  public static Eventspy.EventspyConfigState.Builder mergeEventspyConfigState(
      Eventspy.EventspyConfigState dst, Eventspy.EventspyConfigState src) {
    Eventspy.EventspyConfigState.Builder builder = dst.toBuilder();
    if (!dst.hasConfig() && src.hasConfig()) {
      builder.setConfig(src.getConfig());
    }
    return builder;
  }

