  public static Map<String, String> eventspyConfigStateToEnvVar(Eventspy.EventspyConfigState msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasConfig()) {
      result.putAll(configToEnvVar(msg.getConfig()));
    }
    return result;
  }

  public static Eventspy.EventspyConfigState.Builder eventspyConfigStateFromEnvVar(
      Map<String, String> env) {
    Eventspy.EventspyConfigState.Builder builder = Eventspy.EventspyConfigState.newBuilder();
    {
      var sub = configFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setConfig(sub);
      }
    }
    return builder;
  }

